mapper.select:
WITH RECURSIVE folder_cte AS (
SELECT id FROM user_folder
WHERE user_id = #{userId}
AND id IN

    #{id}

UNION ALL
SELECT f.id FROM user_folder f
INNER JOIN folder_cte c ON f.parent_id = c.id
WHERE f.user_id = #{userId}
)
SELECT uf.id FROM user_file uf
WHERE uf.user_id = #{userId}
AND uf.parent_id IN (SELECT id FROM folder_cte)

update.foreach:
UPDATE user_file
SET deleted_at = NULL, name = #{item.name}
WHERE id = #{item.id}
